def parse_logs():
    for i in range(500_000):
        level = 'ERROR' if i % 100 == 0 else 'INFO'
        yield f'2026-03-28 [level={level}] Evento {i}'

def filter_errors(stream):
    for line in stream:
        if '[level=ERROR]' in line:
            yield line

conteo = sum(1 for _ in filter_errors(parse_logs()))
print(f'Total de eventos criticos procesados en streaming: {conteo}')
